#include "RecoveryRetention.h"
static void testRecoveryRetention(const File& parent){
    auto root=parent.getChildFile("retention-"+Uuid().toString());root.createDirectory();auto history=root.getChildFile("data/History");history.createDirectory();auto now=Time::currentTimeMillis();RecoveryRetentionPolicy policy;
    expect(!policy.automatic&&policy.keepNewest>=2,"automatic deletion is opt-in and defaults protect at least two verified copies");
    auto prefs=root.getChildFile("data/recovery-retention.json");auto configured=policy;configured.keepNewest=3;configured.maxAgeDays=0;configured.maxMiB=12;configured.automatic=true;RecoveryRetentionPolicy loaded;
    expect(saveRecoveryRetention(prefs,configured).wasOk()&&loadRecoveryRetention(prefs,loaded).wasOk()&&loaded==configured,"local retention preferences round trip all explicit limits and opt-in state");
    for(int which=0;which<6;++which){auto bad=policy;if(which==0)bad.keepNewest=1;if(which==1)bad.keepNewest=2001;if(which==2)bad.maxAgeDays=-1;if(which==3)bad.maxAgeDays=3651;if(which==4)bad.maxMiB=0;if(which==5)bad.maxMiB=32769;auto before=prefs.loadFileAsString();expect(saveRecoveryRetention(prefs,bad).failed()&&prefs.loadFileAsString()==before,"invalid retention limits cannot replace saved settings");}
    prefs.replaceWithText("{\"schema\":1,\"keepNewest\":true,\"maxAgeDays\":30,\"maxMiB\":256,\"automatic\":false}");expect(loadRecoveryRetention(prefs,loaded).failed()&&loaded==configured,"boolean values cannot silently become numeric retention settings");prefs.replaceWithText("{broken");expect(loadRecoveryRetention(prefs,loaded).failed()&&loaded==configured,"damaged settings retain the caller's previous policy");
    auto obstruction=root.getChildFile("blocked.json");obstruction.createDirectory();expect(saveRecoveryRetention(obstruction,policy).failed()&&obstruction.isDirectory(),"preferences never replace a directory");
    RecoveryCleanupPlan plan;expect(planRecoveryCleanup(root,policy,plan).wasOk()&&plan.archives.empty()&&plan.remove.empty(),"empty recovery history produces a harmless empty plan");
    auto seed=[&](const String& title,int age,int padding=0){auto project=emptyProject();project.title=title;project.notes=String::repeatedString("x",padding);auto draft=root.getChildFile(Uuid().toString()+".pulse");saveProject(project,draft);auto target=history.getChildFile("Recovery_"+projectFileToken(draft)+".pulse");draft.moveFileTo(target);target.setLastModificationTime(Time(now-(int64)age*86400000));return target;};
    std::vector<File> originals;for(int i=0;i<6;++i)originals.push_back(seed("Archived "+String(i),i));policy.keepNewest=3;policy.maxAgeDays=0;expect(planRecoveryCleanup(root,policy,plan,nullptr,now).wasOk()&&plan.archives.size()==6&&plan.remove.size()==3&&plan.remove.front()==5,"count limit plans deletion oldest first and keeps the newest requested copies");
    auto total=plan.totalBytes;policy.keepNewest=2000;policy.maxAgeDays=1;expect(planRecoveryCleanup(root,policy,plan,nullptr,now).wasOk()&&plan.remove.size()==4&&plan.remove.back()==2,"age expiry independently removes old copies but protects the newest two");
    policy.maxAgeDays=0;expect(planRecoveryCleanup(root,policy,plan,nullptr,now).wasOk()&&plan.remove.empty()&&plan.totalBytes==total,"zero age disables expiry without changing accounted archive bytes");
    auto manual=history.getChildFile("Before_open_keep.pulse");manual.replaceWithText("KEEP");auto damaged=history.getChildFile("Recovery_"+String::repeatedString("a",64)+".pulse");damaged.replaceWithText("{damaged");auto misnamed=history.getChildFile("Recovery_"+String::repeatedString("b",64)+".pulse");saveProject(emptyProject(),misnamed);auto unrelated=history.getChildFile("User song.pulse");saveProject(emptyProject(),unrelated);auto sub=history.getChildFile("Subfolder");sub.createDirectory();auto nested=sub.getChildFile(originals.back().getFileName());originals.back().copyFileTo(nested);auto primary=root.getChildFile("data/recovery-v0.29.pulse");saveProject(emptyProject(),primary);auto backup=projectBackupFile(primary);saveProject(emptyProject(),backup);auto versions=root.getChildFile("data/Versions/Manual.pulse");saveProject(emptyProject(),versions);
    policy.keepNewest=2;expect(planRecoveryCleanup(root,policy,plan,nullptr,now).wasOk()&&plan.archives.size()==6&&plan.excluded==5,"only exact hash-matching readable managed archives enter a cleanup plan");
    std::atomic<bool> cancel{true};auto retained=plan;expect(planRecoveryCleanup(root,policy,plan,&cancel,now).failed()&&plan.archives==retained.archives,"cancelled scanning does not publish partial results");RecoveryCleanupResult result;expect(applyRecoveryCleanup(plan,result,&cancel).failed()&&result.removed==0&&originals.back().existsAsFile(),"cancelled application retains every reviewed copy");cancel.store(false);
    auto forged=plan;forged.remove.push_back(0);expect(applyRecoveryCleanup(forged,result).failed()&&result.removed==0&&originals[0].existsAsFile(),"a forged plan cannot delete a protected newest copy");forged=plan;forged.archives.back().file=versions;expect(applyRecoveryCleanup(forged,result).failed()&&versions.existsAsFile(),"a forged external path cannot redirect cleanup into manual versions");
    auto changed=originals.back();auto originalText=changed.loadFileAsString();changed.replaceWithText("changed after review");expect(applyRecoveryCleanup(plan,result).failed()&&result.removed==0&&originals[4].existsAsFile(),"content changes after review reject the whole deletion list before its first removal");changed.replaceWithText(originalText);changed.setLastModificationTime(Time(now-5LL*86400000));planRecoveryCleanup(root,policy,plan,nullptr,now);auto added=seed("Arrived after review",0);expect(applyRecoveryCleanup(plan,result).failed()&&result.removed==0&&added.existsAsFile(),"new recovery arrivals invalidate an older review before deleting any copy");
    planRecoveryCleanup(root,policy,plan,nullptr,now);auto count=plan.remove.size();expect(applyRecoveryCleanup(plan,result).wasOk()&&result.removed==(int)count&&result.bytes==plan.removeBytes,"reviewed cleanup removes exactly its checked files and reports reclaimed bytes");expect(originals[0].existsAsFile()&&added.existsAsFile(),"the newest two recoveries remain after count-based deletion");expect(manual.loadFileAsString()=="KEEP"&&damaged.loadFileAsString()=="{damaged"&&misnamed.existsAsFile()&&unrelated.existsAsFile()&&nested.existsAsFile()&&primary.existsAsFile()&&backup.existsAsFile()&&versions.existsAsFile(),"cleanup preserves current recovery backups manual versions safety history nested files and damaged evidence");
    expect(applyRecoveryCleanup(plan,result).failed()&&result.removed==0,"an already applied review cannot be replayed against changed history");
    auto large=parent.getChildFile("retention-size-"+Uuid().toString());large.createDirectory();root=large;history=root.getChildFile("data/History");history.createDirectory();for(int i=0;i<4;++i)seed("Large "+String(i),i,600000);policy.keepNewest=2000;policy.maxMiB=1;policy.maxAgeDays=0;expect(planRecoveryCleanup(root,policy,plan,nullptr,now).wasOk()&&plan.remove.size()==2&&plan.totalBytes-plan.removeBytes>1024*1024,"size cleanup protects the newest two even when their bytes exceed the requested budget");expect(recoveryCleanupSummary(plan).containsIgnoreCase("newest two")&&recoveryCleanupSummary(plan).contains("Remove 2"),"cleanup summary describes retained and removed copy counts");
    auto blockedRoot=parent.getChildFile("retention-blocked-"+Uuid().toString());blockedRoot.createDirectory();blockedRoot.getChildFile("data").replaceWithText("KEEP");expect(planRecoveryCleanup(blockedRoot,policy,plan).failed()&&blockedRoot.getChildFile("data").loadFileAsString()=="KEEP","non-directory data roots reject cleanup without touching their bytes");
}

static int retentionProbe(int argc,char** argv){
    if(argc!=3)return 2;auto root=File(String::fromUTF8(argv[2]));if(!root.isAChildOf(File::getCurrentWorkingDirectory().getChildFile("test-output")))return 2;
    RecoveryRetentionPolicy policy;policy.keepNewest=2;policy.maxAgeDays=0;RecoveryCleanupPlan plan;RecoveryCleanupResult removed;auto result=planRecoveryCleanup(root,policy,plan);if(result.wasOk())result=applyRecoveryCleanup(plan,removed);auto* object=new DynamicObject();object->setProperty("ok",result.wasOk());object->setProperty("removed",removed.removed);object->setProperty("message",result.getErrorMessage());std::cout<<JSON::toString(var(object),true).toStdString()<<"\n";return 0;
}
